/// <summary>What the host receives for an action (SPEC §2.2): its name, the element id, and inside
/// a list the data path of the item, such as <c>$.todos.2</c>.</summary>
public sealed record WeftEvent(string Action, string? Id, string? Item);

/// <summary>The command of one action: it hands every event to the view model's <c>Perform</c>.</summary>
public sealed class WeftCommand : ICommand
{
    private readonly Action<string, string?, string?> perform;

    public WeftCommand(string name, Action<string, string?, string?> perform)
    {
        Name = name;
        this.perform = perform;
    }

    public string Name { get; }

    // An action is always available: a control's `disabled` is drawn by the control itself.
    public event EventHandler? CanExecuteChanged { add { } remove { } }

    public bool CanExecute(object? parameter) => true;

    public void Execute(object? parameter)
    {
        var e = parameter as WeftEvent;
        perform(Name, e?.Id, e?.Item);
    }
}

/// <summary>An item of a generated list. Its view model places it, so an event inside a list
/// carries the item's path and a template reaches the view model and the enclosing item.</summary>
public interface IWeftItem
{
    string WeftPath { get; }

    void WeftPlace(object root, object? parent, string path);
}

/// <summary>The functions generated bindings call.</summary>
public static class Weft
{
    /// <summary>SPEC §2.1: false, 0, an empty string and null are falsy; an empty list or object is not.</summary>
    public static bool Truthy(object? value) => value switch
    {
        null => false,
        bool b => b,
        string s => s.Length > 0,
        double d => d != 0 && !double.IsNaN(d),
        int i => i != 0,
        _ => true,
    };

    public static bool Not(object? value) => !Truthy(value);

    /// <summary>A bound <c>hidden</c>. x:Bind turns a <c>bool</c> property into a
    /// <c>Visibility</c>, but not the result of a function.</summary>
    public static Visibility Hide(object? value) => Truthy(value) ? Visibility.Collapsed : Visibility.Visible;

    /// <summary>Tells each item of a list where it sits: <c>path.index</c>, under <c>parent</c>.</summary>
    public static void Place<T>(IList<T> list, object root, object? parent, string path)
    {
        for (var i = 0; i < list.Count; i++)
        {
            if (list[i] is IWeftItem item)
            {
                item.WeftPlace(root, parent, $"{path}.{i}");
            }
        }
    }

    internal static DependencyProperty Marker(string name, Type owner) =>
        DependencyProperty.RegisterAttached(name, typeof(object), owner, new PropertyMetadata(null));
}

