/// <summary>A dialog's <c>open</c>, two-way: true shows the dialog, false hides it, and a
/// dismissal by the user writes false back and runs the dialog's <c>close</c>, which a dialog the
/// view model hides does not.</summary>
public static class Dialog
{
    public static readonly DependencyProperty IsOpenProperty = DependencyProperty.RegisterAttached(
        "IsOpen", typeof(bool), typeof(Dialog), new PropertyMetadata(false, Changed));

    private static readonly DependencyProperty HookedProperty =
        DependencyProperty.RegisterAttached("Hooked", typeof(bool), typeof(Dialog), new PropertyMetadata(false));

    public static bool GetIsOpen(DependencyObject o) => (bool)o.GetValue(IsOpenProperty);
    public static void SetIsOpen(DependencyObject o, bool value) => o.SetValue(IsOpenProperty, value);

    private static void Changed(DependencyObject o, DependencyPropertyChangedEventArgs e)
    {
        if (o is not ContentDialog dialog)
        {
            return;
        }
        if (!(bool)o.GetValue(HookedProperty))
        {
            o.SetValue(HookedProperty, true);
            dialog.Closed += (_, _) =>
            {
                // Still open in the model: the user dismissed it.
                if (GetIsOpen(dialog))
                {
                    SetIsOpen(dialog, false);
                    On.Closed(dialog);
                }
            };
        }
        if (!(bool)e.NewValue)
        {
            dialog.Hide();
        }
        else if (dialog.XamlRoot is null)
        {
            // A dialog shows only once it has a XamlRoot, which it gets when the page loads.
            dialog.Loaded += Show;
        }
        else
        {
            Show(dialog, null);
        }
    }

    private static async void Show(object sender, RoutedEventArgs? _)
    {
        var dialog = (ContentDialog)sender;
        dialog.Loaded -= Show;
        if (!GetIsOpen(dialog))
        {
            return;
        }
        try
        {
            await dialog.ShowAsync();
        }
        catch (Exception)
        {
            // One dialog at a time: a second one stays closed, and the model says so.
            SetIsOpen(dialog, false);
        }
    }
}

/// <summary>The events of the catalog as attached commands, such as
/// <c>weft:On.Press="{x:Bind ViewModel.saveCommand}"</c>. Each runs its command with the element's
/// <c>AutomationId</c> and, inside a list, the path of the item the element shows.</summary>
public static class On
{
    public static readonly DependencyProperty PressProperty = Event("Press");
    public static readonly DependencyProperty ChangeProperty = Event("Change");
    public static readonly DependencyProperty SubmitProperty = Event("Submit");
    public static readonly DependencyProperty CloseProperty = Event("Close");

    // Set once an element listens, so a second event on it adds no second handler.
    private static readonly DependencyProperty HookedProperty =
        DependencyProperty.RegisterAttached("Hooked", typeof(bool), typeof(On), new PropertyMetadata(false));

    public static ICommand? GetPress(DependencyObject o) => (ICommand?)o.GetValue(PressProperty);
    public static void SetPress(DependencyObject o, ICommand? value) => o.SetValue(PressProperty, value);
    public static ICommand? GetChange(DependencyObject o) => (ICommand?)o.GetValue(ChangeProperty);
    public static void SetChange(DependencyObject o, ICommand? value) => o.SetValue(ChangeProperty, value);
    public static ICommand? GetSubmit(DependencyObject o) => (ICommand?)o.GetValue(SubmitProperty);
    public static void SetSubmit(DependencyObject o, ICommand? value) => o.SetValue(SubmitProperty, value);
    public static ICommand? GetClose(DependencyObject o) => (ICommand?)o.GetValue(CloseProperty);
    public static void SetClose(DependencyObject o, ICommand? value) => o.SetValue(CloseProperty, value);

    private static DependencyProperty Event(string name) =>
        DependencyProperty.RegisterAttached(name, typeof(ICommand), typeof(On), new PropertyMetadata(null, Hook));

    private static void Hook(DependencyObject o, DependencyPropertyChangedEventArgs _)
    {
        if (o is not FrameworkElement element || (bool)o.GetValue(HookedProperty))
        {
            return;
        }
        o.SetValue(HookedProperty, true);
        switch (element)
        {
            case ToggleButton toggle:
                toggle.Click += (_, _) => Fire(toggle, ChangeProperty);
                break;
            case ButtonBase button:
                // One handler, so a press always runs before the form's submit (SPEC §5.1).
                button.Click += (_, _) =>
                {
                    Fire(button, PressProperty);
                    Fire(button, SubmitProperty);
                };
                break;
            case ToggleSwitch toggle:
                toggle.Toggled += (_, _) => Edited(toggle);
                break;
            case TextBox text:
                text.TextChanged += (_, _) => Edited(text);
                break;
            case PasswordBox password:
                password.PasswordChanged += (_, _) => Edited(password);
                break;
            case ListViewItem item:
                item.Loaded += (_, _) => Clicks(ItemsControl.ItemsControlFromItemContainer(item) as ListViewBase);
                break;
            case ContentDialog:
                // Dialog.IsOpen runs close, so a dialog the view model hides runs none.
                break;
            default:
                // A table row presses on a tap. A form: Enter in one of its single-line fields
                // submits it, even when the field handled the key itself.
                element.Tapped += (_, _) => Fire(element, PressProperty);
                element.AddHandler(UIElement.KeyDownEvent, new KeyEventHandler(Entered), true);
                break;
        }
    }

    internal static void Closed(FrameworkElement dialog) => Fire(dialog, CloseProperty);

    // A list reports a press of an item, by click or key, once its IsItemClickEnabled is on.
    private static void Clicks(ListViewBase? list)
    {
        if (list is null || (bool)list.GetValue(HookedProperty))
        {
            return;
        }
        list.SetValue(HookedProperty, true);
        list.IsItemClickEnabled = true;
        list.ItemClick += (_, e) =>
        {
            // The clicked item is the ListViewItem itself, or the content it shows.
            var item = e.ClickedItem as ListViewItem
                ?? Ancestor(e.ClickedItem as DependencyObject)
                ?? list.Items.OfType<ListViewItem>().FirstOrDefault(i => ReferenceEquals(i.Content, e.ClickedItem));
            if (item is not null)
            {
                Fire(item, PressProperty);
            }
        };
    }

    private static ListViewItem? Ancestor(DependencyObject? o)
    {
        while (o is not null and not ListViewItem)
        {
            o = VisualTreeHelper.GetParent(o);
        }
        return o as ListViewItem;
    }

    // A value the view model writes into the control is not the user's change.
    private static void Edited(Control control)
    {
        if (control.FocusState != FocusState.Unfocused)
        {
            Fire(control, ChangeProperty);
        }
    }

    private static void Entered(object sender, KeyRoutedEventArgs e)
    {
        var field = e.OriginalSource is TextBox { AcceptsReturn: false } || e.OriginalSource is PasswordBox;
        if (e.Key == VirtualKey.Enter && field && sender is FrameworkElement form)
        {
            Fire(form, SubmitProperty);
        }
    }

    private static void Fire(FrameworkElement element, DependencyProperty property)
    {
        if (element.GetValue(property) is not ICommand command)
        {
            return;
        }
        var id = AutomationProperties.GetAutomationId(element);
        var item = (element.DataContext as IWeftItem)?.WeftPath;
        command.Execute(new WeftEvent((command as WeftCommand)?.Name ?? "", string.IsNullOrEmpty(id) ? null : id, item));
    }
}
